/**
 * emit to subscription queries of type FindDispute,
 * but only if the id matches
 *
 * @param		entity	Dispute
 */
	protected void emitFindDispute( Dispute entity ) {
		LOGGER.info("handling emitFindDispute" );
		
	    queryUpdateEmitter.emit(FindDisputeQuery.class,
	                            query -> query.getFilter().getDisputeId().equals(entity.getDisputeId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDispute
	 * 
	 * @param		entity	Dispute
	 */
	protected void emitFindAllDispute( Dispute entity ) {
		LOGGER.info("handling emitFindAllDispute" );
		
	    queryUpdateEmitter.emit(FindAllDisputeQuery.class,
	                            query -> true,
	                            entity);
	}

